#!/usr/sbin/nft -f
flush ruleset                                    <- zacznij od czystej karty
table inet filter {                              <- TABELA: rodzina inet = IPv4 + IPv6
    set admin {                                  <- ZESTAW nazwany
        type ipv4_addr; flags interval
        elements = { 192.168.56.0/24 }
    }
    chain input {                                <- LANCUCH bazowy
        type filter hook input priority filter; policy drop;
        ct state established,related accept     <- REGULY od gory
        ct state invalid drop
        iif "lo" accept
        meta l4proto { icmp, ipv6-icmp } accept
        tcp dport 22 ip saddr @admin accept      <- uzycie zestawu
        tcp dport { 80, 443 } accept             <- zestaw anonimowy
        limit rate 5/minute log prefix "nft-drop: "
    }                                            <- koniec: polityka drop
    chain forward { type filter hook forward priority filter; policy drop; }
    chain output  { type filter hook output  priority filter; policy accept; }
}
iptables:  iptables -A INPUT -p tcp -s 192.168.56.0/24 --dport 22 -j ACCEPT
nft:       nft add rule inet filter input ip saddr 192.168.56.0/24 tcp dport 22 accept

